mapper.select:
SELECT t.table_id, t.capacity, COALESCE(d.table_daily_status, 1) AS table_daily_status, r.reservation_date, r.reservation_time, r.reservation_phone, r.reservation_name, r.reservation_count, r.reservation_adult_count, r.reservation_child_count, r.reservation_status, r.child_seat, r.reservation_note,
CASE WHEN COALESCE(d.table_daily_status, 1) = 0 THEN '未開放' WHEN r.table_id IS NOT NULL AND r.reservation_status = TRUE THEN '使用中' WHEN r.table_id IS NOT NULL THEN '已預約' ELSE '可預約' END AS table_status
FROM tables t
LEFT JOIN table_daily d ON t.table_id = d.table_id AND d.table_daily_date = #{reservationDate}
LEFT JOIN reservation r ON t.table_id = r.table_id AND r.reservation_date = #{reservationDate} AND r.reservation_time = #{reservationTime} ORDER BY t.table_id;
